pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;
    function setUp() public {
        deployer = address(this);
        c = new C();
    }
    function testFuzz_property(address caller, address newOwner) public {
        // Admissible domain: caller must not be the deployer (the untouched admin)
        vm.assume(caller != deployer);
        // Record the owner before the call
        address ownerBefore = c.owner();
        // Drive the call under the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // After the call, read back owner
        address ownerAfter = c.owner();
        // The reference invariant: if caller is not the original deployer,
        // the owner MUST NOT change. The bug can break this because the
        // owner check lets the current owner (who is not the deployer) succeed.
        assertTrue(ownerAfter == ownerBefore);
    }
}

