pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner) public {
        // actor must be payable EOA; vm.assume restricts to non-zero to avoid precompile collisions
        vm.assume(actor != address(0) && actor != address(c));
        // Also ensure newOwner is a payable address (still an EOA whose code size is 0)
        vm.assume(newOwner != address(0));
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool returned;
        try c.setOwner(newOwner) returns (bool ok) {
            // call did not revert; check that the protocol invariant holds:
            // if msg.sender is admin (the deployer), ok MUST be true AND owner MUST be newOwner.
            // if msg.sender is NOT admin, this block is unreachable because the call would revert.
            returned = ok;
        } catch {
            returned = false;
        }
        // Because actor is NOT the admin (admin is setUp's msg.sender), a legitimate implementation
        // MUST revert, so returned MUST be false.
        // The buggy version fails to revert and returns false — we catch that inconsistency via the require below.
        // General rule: a non-admin call MUST revert.
        // The bug breaks it: non-admin call succeeds returning false.
        assertEq(address(c).balance, 0); // no payable function altered balance
        require(!returned, "Non-admin call should revert; bug returned false");
    }
}

