pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _owner) public {
        // The onlyAdmin modifier checks msg.sender == admin.
        // admin is set to the test contract's address during deployment,
        // so we must prank to admin ourselves.
        address admin = address(this);
        // Exclude the zero address to make the call non-trivial.
        vm.assume(_owner != address(0));

        vm.prank(admin);
        (bool ok, bytes memory ret) = address(c).call(abi.encodeWithSignature("setOwner(address)", _owner));

        assertTrue(ok); // call succeeds (does not revert)

        // The return value MUST be abi-encoded true (bool=1) for the reference.
        // The mutant omits the return, so Solidity returns the default zero bytes (bool=0).
        bool returned = abi.decode(ret, (bool));
        assertTrue(returned);
    }
}

