import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        vm.assume(_newOwner != address(0));
        address admin = address(uint160(uint256(keccak256(abi.encodePacked("admin")))));
        vm.assume(_newOwner != admin);
        // The admin is the original deployer of setUp, but deployer in setUp is this contract.
        // The C(constructor) stores msg.sender as admin, which is the InvMutTest contract address.
        // So we must prank as the test contract itself to satisfy the onlyAdmin modifier in P.
        vm.startPrank(address(this));
        bool success;
        try c.setOwner(_newOwner) returns (bool res) {
            success = res;
        } catch {
            success = false;
        }
        vm.stopPrank();
        assertTrue(success);
    }
}
